class DefaultAdapter {
    constructor(editor, validator) {
        this.editor = editor;
        this.validator = validator;
        this.validationRequestsCallbacks = [];
        const handler = args => {
            this.validationRequestsCallbacks.forEach(item => item(args))
        };
        editor.validationRequest.add(handler);
        editor.on("disposing", () => {
            editor.validationRequest.remove(handler)
        })
    }
    getValue() {
        const {
            value: value
        } = this.editor.option();
        return value
    }
    getCurrentValidationError() {
        const {
            validationError: validationError
        } = this.editor.option();
        return validationError
    }
    bypass() {
        const {
            disabled: disabled
        } = this.editor.option();
        return disabled
    }
    applyValidationResults(params) {
        this.editor.option({
            validationErrors: params.brokenRules,
            validationStatus: params.status
        })
    }
    reset() {
        this.editor.clear()
    }
    focus() {
        this.editor.focus()
    }
}
export default DefaultAdapter;
